# Type Guards and Narrowing

## Problem
TypeScript cannot always infer specific types from union types, requiring manual type checks.

## Solution
Use type guards to narrow types safely.

## Patterns

### 1. typeof Type Guards
```typescript
function processValue(value: string | number) {
  if (typeof value === 'string') {
    return value.toUpperCase(); // TypeScript knows it's a string
  }
  return value.toFixed(2); // TypeScript knows it's a number
}
```

### 2. instanceof Type Guards
```typescript
class Dog {
  bark() { console.log('Woof!'); }
}

class Cat {
  meow() { console.log('Meow!'); }
}

function makeSound(animal: Dog | Cat) {
  if (animal instanceof Dog) {
    animal.bark();
  } else {
    animal.meow();
  }
}
```

### 3. Custom Type Guards
```typescript
interface User {
  name: string;
  email: string;
}

interface Admin extends User {
  permissions: string[];
}

function isAdmin(user: User | Admin): user is Admin {
  return 'permissions' in user;
}

function grantAccess(user: User | Admin) {
  if (isAdmin(user)) {
    console.log('Admin permissions:', user.permissions);
  }
}
```

### 4. Discriminated Unions
```typescript
type Success = { status: 'success'; data: any };
type Error = { status: 'error'; message: string };
type Result = Success | Error;

function handleResult(result: Result) {
  if (result.status === 'success') {
    console.log(result.data); // TypeScript knows it's Success
  } else {
    console.log(result.message); // TypeScript knows it's Error
  }
}
```

## Benefits
- Type safety at runtime
- Better IntelliSense support
- Prevents runtime errors
- Self-documenting code

# Builder Pattern for Configuration

## Problem
Creating objects with many optional parameters leads to telescope constructors or unclear object literals.

## Solution
Use the Builder pattern with fluent interface.

## Implementation

```typescript
interface DatabaseConfig {
  host: string;
  port: number;
  database: string;
  username?: string;
  password?: string;
  ssl?: boolean;
  poolSize?: number;
  timeout?: number;
}

class DatabaseConfigBuilder {
  private config: Partial<DatabaseConfig> = {
    port: 5432,
    poolSize: 10,
    timeout: 30000
  };

  host(host: string): this {
    this.config.host = host;
    return this;
  }

  port(port: number): this {
    this.config.port = port;
    return this;
  }

  database(database: string): this {
    this.config.database = database;
    return this;
  }

  credentials(username: string, password: string): this {
    this.config.username = username;
    this.config.password = password;
    return this;
  }

  enableSSL(): this {
    this.config.ssl = true;
    return this;
  }

  poolSize(size: number): this {
    this.config.poolSize = size;
    return this;
  }

  timeout(ms: number): this {
    this.config.timeout = ms;
    return this;
  }

  build(): DatabaseConfig {
    if (!this.config.host || !this.config.database) {
      throw new Error('Host and database are required');
    }
    return this.config as DatabaseConfig;
  }
}

// Usage
const config = new DatabaseConfigBuilder()
  .host('localhost')
  .database('myapp')
  .credentials('admin', 'secret')
  .enableSSL()
  .poolSize(20)
  .build();
```

## Benefits
- Readable configuration
- Type-safe parameter passing
- Validation in build() method
- Immutable final object
- IDE autocomplete support

## When to Use
- Objects with 5+ configuration options
- Many optional parameters
- Need for validation before creation
- Configuration classes

# Result Type for Error Handling

## Problem
Exception-based error handling can be unpredictable and hard to track.

## Solution
Use a Result type that explicitly represents success or failure.

## Implementation

```typescript
type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

// Helper functions
function Ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function Err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

// Usage example
interface User {
  id: string;
  name: string;
}

function findUserById(id: string): Result<User, string> {
  if (id === '123') {
    return Ok({ id: '123', name: 'John Doe' });
  }
  return Err(`User not found: ${id}`);
}

function updateUserName(
  userId: string,
  newName: string
): Result<User, string> {
  const userResult = findUserById(userId);

  if (!userResult.ok) {
    return Err(userResult.error);
  }

  const updatedUser = { ...userResult.value, name: newName };
  return Ok(updatedUser);
}

// Consuming the Result
const result = updateUserName('123', 'Jane Doe');

if (result.ok) {
  console.log('Updated user:', result.value);
} else {
  console.error('Error:', result.error);
}
```

## Advanced: Result with Methods

```typescript
class Result<T, E = Error> {
  private constructor(
    private readonly success: boolean,
    private readonly data?: T,
    private readonly err?: E
  ) {}

  static ok<T>(value: T): Result<T, never> {
    return new Result(true, value);
  }

  static err<E>(error: E): Result<never, E> {
    return new Result(false, undefined, error);
  }

  isOk(): this is { data: T } {
    return this.success;
  }

  isErr(): this is { err: E } {
    return !this.success;
  }

  map<U>(fn: (value: T) => U): Result<U, E> {
    if (this.isOk()) {
      return Result.ok(fn(this.data));
    }
    return Result.err(this.err);
  }

  flatMap<U>(fn: (value: T) => Result<U, E>): Result<U, E> {
    if (this.isOk()) {
      return fn(this.data);
    }
    return Result.err(this.err);
  }

  unwrap(): T {
    if (this.isOk()) {
      return this.data;
    }
    throw new Error('Called unwrap on an error result');
  }

  unwrapOr(defaultValue: T): T {
    return this.isOk() ? this.data : defaultValue;
  }
}
```

## Benefits
- Explicit error handling
- Type-safe error propagation
- No hidden exceptions
- Forces developers to handle errors
- Composable with map/flatMap

## When to Use
- Functions that can fail
- Validation logic
- External API calls
- File I/O operations
- Database queries
